By replacing $\mathcal{U}^L$ with an open neighborhood of $\mathcal{U} \subset \mathcal{U}^L$ as in Remark~8.13 if necessary, 
there is a semiorthogonal decomposition 
\begin{align}
\operatorname{M}_{\mathbb{G}_m}((\mathcal{V}^L)^{\vee})_{\delta}=\langle \Upsilon_{\mathcal{V}} (\operatorname{M}_{\mathbb{G}_m}(\mathcal{Z}_{\mathcal{V}})_{\delta'}), \operatorname{M}_{\mathbb{G}_m}((\mathcal{V}^L)^{\vee})_{\delta} \cap 
\mathcal{W}_{\mathcal{V}, \delta}\rangle. 
\end{align}
Moreover the functor (8.39) is fully-faithful and 
(8.38) restricts to an equivalence 
\begin{align}
\Phi \colon 
\operatorname{M}_{\mathbb{G}_m}((\mathcal{V}^L)^{\vee})_{\delta} \cap \mathcal{W}_{\mathcal{V}, \delta} \stackrel{\sim}{\to}
\operatorname{M}_{\mathbb{G}_m}((\mathcal{V}^L)^{\vee}_{\circ})_{\delta}.     
\end{align}

For the open immersion $j \colon \mathcal{U}_{\circ} \hookrightarrow \mathcal{U}$, 
its pull-back 
\[j^{\ast} \colon \operatorname{L}(\mathcal{U})_{\delta} \to \operatorname{L}(\mathcal{U}_{\circ})_{\delta}\]
admits a fully-faithful left adjoint 
\begin{align}
	j_{!} \colon \operatorname{L}(\mathcal{U}_{\circ})_{\delta} \hookrightarrow \operatorname{L}(\mathcal{U})_{\delta}	
\end{align}
and the semiorthogonal decomposition 
	\begin{align}
		\operatorname{L}(\mathcal{U})_{\delta}=
		\langle \Upsilon_{\mathcal{U}} \operatorname{L}(\mathcal{Z})_{\delta'}, j_{!}\operatorname{L}(\mathcal{U}_{\circ})_{\delta} \rangle. 
		\end{align}
	Here $\delta'=\delta \otimes (\det \mathbb{L}_{p})^{1/2}|_{\mathcal{Z}}$, and 
    the functor $\Upsilon_{\mathcal{U}}$ is fully-faithful on $\operatorname{L}(\mathcal{Z})_{\delta'}$.

The dg-category (7.7) is compactly generated. Its subcategory 
of compact objects 
$\operatorname{L}(\mathrm{Higgs}_G(\chi))_w$ admits a semiorthogonal decomposition 
\begin{align*}
    \operatorname{L}(\mathrm{Higgs}_G(\chi))_w=\left\langle \mathbb{T}_{M}(\chi_{M})_{w_{M}} : \begin{array}{ll}
     \mu_M(\chi_{M})\in N(T)_{\mathbb{Q}+}^{W_M} \\ \mu_M(w_M)=\mu_G(w) \end{array}\right\rangle.
\end{align*}
   Here the right-hand side is after all standard parabolics $P\subset G$ with 
    Levi quotient $P\twoheadrightarrow M$, satisfying
    \begin{align*}(\chi_{M}, w_{M}) \in \pi_1(M) \times Z(M)^{\vee}, \mathbb{}a_{M}(\chi_{M}, w_{M})=(\chi, w).
    \end{align*}

\begin{align}
\operatorname{L}(\mathcal{U})_{\delta}=\langle \operatorname{L}(\mathcal{Z})_{\delta'}, j_{!}\operatorname{L}(\mathcal{U}_{\circ})_{\delta}\rangle.
\end{align}
